  function pfArenaSetActiveFromHand(who,uid,silent=false){const side=pfSide(who);if(!side||side.active)return false;const idx=side.hand.findIndex(f=>f.uid===uid);if(idx<0)return false;const [f]=side.hand.splice(idx,1);side.active=f;side.nextEnergy=f.type;pfStartActive(f);pfLog(`${who==='player'?'You':'Rival'} placed ${f.card.name} in the Active spot.`);pfArenaSelection=null;pfArenaFight.mode=null;if(!silent)renderCampaigns();return true}
  function pfArenaSetupRival(side){if(!side?.hand?.length)return;const score=f=>f.atk*1.1+f.maxHp*.34+f.abilities.length*7;const active=side.hand.slice().sort((a,b)=>score(b)-score(a))[0];const i=side.hand.findIndex(f=>f.uid===active.uid);side.active=side.hand.splice(i,1)[0];side.nextEnergy=side.active.type;pfStartActive(side.active);const benchCount=2;for(let n=0;n<benchCount&&side.hand.length;n++){const best=side.hand.slice().sort((a,b)=>score(b)-score(a))[0];const j=side.hand.findIndex(f=>f.uid===best.uid);side.bench[n]=side.hand.splice(j,1)[0]}}
  function pfArenaReadyBattle(){if(!pfArenaFight||pfArenaFight.phase!=='setup'||!pfArenaFight.player.active)return;pfArenaFight.phase='battle';pfArenaFight.turn=pfArenaFight.starting;pfArenaSelection=null;pfArenaFight.mode=null;pfLog('Battle ready.');renderCampaigns();setTimeout(pfArenaBeginTurn,260)}
  function pfArenaStartFight(){const mine=pfArenaResolvedDeck(),r=pfArenaPreview;if(mine.length!==10||!r)return;const seed=Date.now()>>>0,userFirst=state.arena.pocketTutorialDone?((seed&1)===0):false,p=pfBuildSide(mine,pfArenaDeckById()?.moves||{},seed^0xabc123),e=pfBuildSide(r.cards,r.moves,seed^0xdef456);pfArenaFight={player:p,enemy:e,turn:'player',starting:userFirst?'player':'enemy',phase:'setup',turnNo:0,seed,theme:r.theme,skill:r.skill,log:['Choose your Active card.'],winner:null,selected:null,mode:null,startedAt:Date.now(),tutorialBattle:!state.arena.pocketTutorialDone};pfArenaSetupRival(e);pfArenaScreen='battle';pfArenaAuto=false;pfArenaSelection=null;renderCampaigns()}
  function pfSide(who){return pfArenaFight?.[who]}
  function pfOther(who){return who==='player'?'enemy':'player'}
  function pfActive(who){return pfSide(who)?.active||null}
  function pfEnergyCount(f){return f?.energy?.length||0}
  function pfHasAbility(f,k){return !!f?.abilities?.includes(k)}
  function pfLog(t){if(!pfArenaFight)return;pfArenaFight.log.unshift(t);pfArenaFight.log=pfArenaFight.log.slice(0,4)}
  function pfDraw(who){const s=pfSide(who);if(s?.draw.length)s.hand.push(s.draw.shift())}
  function pfHeal(f,n){if(!f)return 0;const before=f.hp;f.hp=Math.min(f.maxHp,f.hp+Math.max(0,Math.round(n)));return f.hp-before}
