  function pfArenaBeginTurn(){if(!pfArenaFight||pfArenaFight.winner||pfArenaFight.phase==='setup')return;const who=pfArenaFight.turn,s=pfSide(who);pfArenaFight.turnNo++;s.turns++;s.energyUsed=false;s.attachedThisTurn=false;s.energyReady=!(pfArenaFight.turnNo===1&&who===pfArenaFight.starting);s.nextEnergy=s.active?.type||PF_BATTLE_TYPES[(pfArenaFight.turnNo+s.turns)%PF_BATTLE_TYPES.length];pfDraw(who);for(const f of [s.active,...s.bench].filter(Boolean))if(pfHasAbility(f,'regen'))pfHeal(f,f.maxHp*.05);pfArenaSelection=null;pfArenaFight.mode=null;pfLog(`${who==='player'?'Your':'Rival'} turn.`);renderCampaigns();if(who==='enemy')setTimeout(()=>pfArenaRunAI('enemy'),pfArenaAuto?180:620);else if(pfArenaAuto)setTimeout(()=>pfArenaRunAI('player'),220)}
  function pfEndTurn(){if(!pfArenaFight||pfArenaFight.winner)return;pfArenaFight.turn=pfOther(pfArenaFight.turn);pfArenaBusy=false;pfArenaBeginTurn()}
  function pfArenaPlayBench(who,uid,silent=false){const s=pfSide(who);if(!s)return false;const idx=s.hand.findIndex(f=>f.uid===uid),slot=s.bench.findIndex(x=>!x);if(idx<0||slot<0)return false;const [f]=s.hand.splice(idx,1);s.bench[slot]=f;pfLog(`${who==='player'?'You':'Rival'} benched ${f.card.name}.`);if(who==='player'&&!silent)sfx('tap');if(!silent)renderCampaigns();return true}
  function pfArenaAttachEnergy(who,targetUid,silent=false){const s=pfSide(who);if(!s||!s.energyReady||s.energyUsed)return false;const f=[s.active,...s.bench].filter(Boolean).find(x=>x.uid===targetUid);if(!f)return false;f.energy.push(s.nextEnergy?.id||f.type.id);s.energyUsed=true;s.attachedThisTurn=true;s.energyReady=false;pfLog(`${who==='player'?'You':'Rival'} attached Energy to ${f.card.name}.`);if(who==='player'&&!silent)sfx('click');pfArenaFight.mode=null;if(!silent)renderCampaigns();return true}
  function pfAdjustedTypeMult(attacker,defender,ignoreResist=false){let m=pfTypeMult(attacker.type,defender.type);if(ignoreResist&&m<1)m=1;if(pfHasAbility(attacker,'pierce')){if(m<=.65)m=.80;else if(m<1)m=.90}return m}
