  function pfArenaAttack(who,kind='basic'){if(!pfArenaFight||pfArenaFight.winner||pfArenaFight.phase==='setup'||pfArenaFight.turn!==who||pfArenaBusy)return false;const a=pfActive(who),d=pfActive(pfOther(who));if(!a||!d)return false;const move=PF_SPECIAL_MOVES[a.move]||PF_SPECIAL_MOVES.burst,cost=kind==='special'?move.cost:1;if(pfEnergyCount(a)<cost)return false;pfArenaBusy=true;let res;if(kind==='special'){if(a.move==='mend'){pfHeal(a,a.maxHp*.32);res=pfDamage(a,d,.70,{special:true})}else if(a.move==='break')res=pfDamage(a,d,1.30,{special:true,ignoreResist:true});else if(a.move==='counter'){a.counterReady=true;res=pfDamage(a,d,1.15,{special:true})}else if(a.move==='rally'){a.rally=1;res=pfDamage(a,d,1.10,{special:true})}else if(a.move==='pivot'){a.freeRetreat=true;res=pfDamage(a,d,1.05,{special:true})}else res=pfDamage(a,d,1.55,{special:true})}else res=pfDamage(a,d,1,{special:false});pfArenaGuide.flags.attacked=who==='player'||pfArenaGuide.flags.attacked;pfLog(res.miss?`${a.card.name}'s attack missed.`:`${a.card.name} dealt ${res.damage}${res.crit?' CRIT':''}.`);sfx(res.miss?'tap':'reward');pfArenaFight.lastAnim={attacker:a.uid,defender:d.uid,damage:res.damage,miss:res.miss,crit:res.crit};renderCampaigns();if(d.hp<=0){setTimeout(()=>pfArenaKnockout(pfOther(who),who),520);return true}setTimeout(pfEndTurn,560);return true}
  function pfArenaKnockout(loser,scorer){const ls=pfSide(loser),ss=pfSide(scorer),dead=ls.active;if(!dead)return;ls.discard.push(dead);ls.active=null;ss.points++;pfLog(`${dead.card.name} was knocked out. ${scorer==='player'?'You':'Rival'} gained 1 point.`);if(ss.points>=3){pfArenaFinish(scorer==='player');return}const available=ls.bench.map((x,i)=>x?i:-1).filter(i=>i>=0);if(!available.length){pfArenaFinish(scorer==='player');return}if(loser==='enemy'){const best=pfAIBestBench('enemy');pfArenaPromote('enemy',best);setTimeout(pfEndTurn,520)}else{pfArenaFight.mode='promote';pfArenaSelection=null;renderCampaigns();if(pfArenaAuto)setTimeout(()=>{const b=pfAIBestBench('player');pfArenaPromote('player',b);pfEndTurn()},260)}}
