  const pfV335ShowViewBase=showView;showView=function(v){pfV335ShowViewBase(v);if(v==='campaigns'){pfArenaScreen=pfArenaFight?'battle':'hub';renderCampaigns();if(!window.__pfMainTutorialActive&&!state.arena.pocketTutorialDone)requestAnimationFrame(pfArenaGuideStart)}else if(pfArenaGuide.active){pfArenaGuideDestroy()}};

  /* Admin Arena lab. */
  if(typeof pfRenderAdminV35==='function'){const pfV335AdminBase=pfRenderAdminV35;pfRenderAdminV35=function(){pfV335AdminBase();const shell=$('#pfAdminV35Shell'),body=$('#pfAdminV35Body');if(!shell||!body)return;const nav=$('[data-v35-admin-tab="campaigns"]');if(nav)nav.textContent='Arena';if(shell.dataset.tab!=='campaigns')return;const r=pfArenaRank();body.innerHTML=`<div class="pf-admin-v35-columns"><section class="pf-admin-v35-card"><h3>Ranked Arena</h3><p>${state.arena.placements<5?`${state.arena.placements}/5 placements · ${state.arena.placementWins} wins`:r.name+' · '+state.arena.rating+' RP'} · ${state.arena.decks.length} deck${state.arena.decks.length===1?'':'s'}</p><div class="pf-admin-v35-btns"><button id="pfV335PlacementWin">Placement Win</button><button id="pfV335PlacementLoss">Placement Loss</button><button id="pfV335AddRP">+100 RP</button><button id="pfV335ResetArena" class="danger">Reset Arena Rank</button></div></section><section class="pf-admin-v35-card"><h3>Arena test tools</h3><div class="pf-admin-v35-btns"><button id="pfV335ResetTutorial">Reset Click Tutorial</button><button id="pfV335CreateDeck">Create Test Deck</button><button id="pfV335Apex">Set Apex</button></div></section></div><div class="pf-admin-v35-card"><h3>Set exact rank</h3><div class="pf-admin-v35-controls"><select id="pfV335RankSelect">${PF_ARENA_RANKS.map(x=>`<option value="${x.min}" ${x.id===r.id?'selected':''}>${x.name}</option>`).join('')}</select><button id="pfV335SetRank">Set Rank</button></div></div>`;const finishPlacement=win=>{if(state.arena.placements>=5){state.arena.placements=0;state.arena.placementWins=0;state.arena.rating=0}if(win)state.arena.placementWins++;state.arena.placements++;if(state.arena.placements===5){const map=[25,95,170,245,320,395];state.arena.rating=map[Math.min(5,state.arena.placementWins)]}save(true);pfArenaApplyRankRibbon();pfRenderAdminV35()};$('#pfV335PlacementWin').onclick=()=>finishPlacement(true);$('#pfV335PlacementLoss').onclick=()=>finishPlacement(false);$('#pfV335AddRP').onclick=()=>{state.arena.placements=5;state.arena.rating=Math.min(699,(state.arena.rating||0)+100);save(true);pfArenaApplyRankRibbon();pfRenderAdminV35()};$('#pfV335ResetArena').onclick=()=>{state.arena.placements=0;state.arena.placementWins=0;state.arena.rating=0;state.arena.wins=0;state.arena.losses=0;state.arena.streak=0;state.arena.bestStreak=0;state.arena.claimedRanks=[];save(true);pfArenaApplyRankRibbon();pfRenderAdminV35()};$('#pfV335ResetTutorial').onclick=()=>{state.arena.pocketTutorialDone=false;save(true);pfRenderAdminV35()};$('#pfV335CreateDeck').onclick=()=>{const owned=pfArenaOwned().slice(0,10);if(owned.length<10){setPfAdminStatus('Need at least 10 owned cards for a test deck.',false,true);return}const id='admin_deck_'+Date.now();state.arena.decks.push({id,name:'Admin Test',cards:owned.map(x=>x.copy.uid),moves:{},wins:0,losses:0,createdAt:Date.now()});state.arena.activeDeckId=id;save(true);pfRenderAdminV35()};$('#pfV335Apex').onclick=()=>{state.arena.placements=5;state.arena.rating=699;save(true);pfArenaApplyRankRibbon();pfRenderAdminV35()};$('#pfV335SetRank').onclick=()=>{state.arena.placements=5;state.arena.rating=Number($('#pfV335RankSelect').value)||0;save(true);pfArenaApplyRankRibbon();pfRenderAdminV35()}}}

  if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.length=0;PF320_PLAYER_LOG.push({version:'3.35',title:'Arena Battle Rebuild',items:['Arena now uses a hand, one Active card, three Bench slots, generated Energy, retreats, two attacks, and first-to-3-points battles.','The first Arena visit is a locked spotlight walkthrough that makes you create a deck, pick cards, assign a move, find a fight, bench a card, attach Energy, and attack.','The Deck Builder now shows the complete PackForge card face while selecting all 10 cards.','Arena opponents remain fully local, generated around your deck strength and theme, with smarter play at higher ranks.','The sidebar collapse control was removed.']})}
