    diamond:{skill:.67,swap:.55,weights:{Epic:15,Legendary:35,Mythic:28,Divine:14,Ultra:4,Secret:4},quality:.12,label:'Elite'},
    master:{skill:.76,swap:.70,weights:{Legendary:12,Mythic:28,Divine:26,Ultra:18,God:8,Ascendant:3,Secret:5},quality:.17,label:'Master'},
