    if(best>=0&&bestScore-current>need){const incoming=s.hand[best],old=s.active;s.hand[best]=old;s.active=incoming;s.roundChangesUsed=1;pfStartActive(incoming);pfLog(`Rival changed Active to ${incoming.card.name}.`)}
