    if(m.leech){const n=pfHeal(a,hpDmg*m.leech);if(n)att.messages.push(`Siphon +${n}`)}if(pfHasAbility(a,'drain'))pfHeal(a,hpDmg*.08);if(m.afterShield)addShield(a,(m.afterShield+a.maxHp*.025)*pfv48Mul(att));
