  function pfv53ThemeUnlockIndex(){state.arena.bestRating=Math.max(Number(state.arena.bestRating||0),state.arena.placements>=5?Number(state.arena.rating||0):0);let idx=0;for(let i=0;i<PF_ARENA_RANKS.length;i++)if(state.arena.bestRating>=PF_ARENA_RANKS[i].min)idx=i;return idx}
  function pfv53ThemeUnlocked(t){if(!t.rank)return true;const i=PF_ARENA_RANKS.findIndex(r=>r.id===t.rank);return i<=pfv53ThemeUnlockIndex()}
  function pfv53ApplyTheme(){const wanted=String(state.settings?.pfTheme||'classic'),t=PFV53_THEMES.find(x=>x.id===wanted&&pfv53ThemeUnlocked(x))||PFV53_THEMES[0];state.settings.pfTheme=t.id;document.body.dataset.pfTheme=t.id;return t}
  function pfv53RenderThemes(){const host=$('#stats-themes');if(!host)return;const active=pfv53ApplyTheme(),best=pfv53ThemeUnlockIndex();host.innerHTML=`<div class="pfv53-theme-head"><small>RANK THEMES</small><h2>Style PackForge</h2><p>Themes unlock permanently as you climb. They are CSS-only and tuned for low-end Chrome hardware.</p></div><div class="pfv53-theme-grid">${PFV53_THEMES.map(t=>{const unlocked=pfv53ThemeUnlocked(t),rank=t.rank?PF_ARENA_RANKS.find(r=>r.id===t.rank):null;return `<button class="pfv53-theme-card ${active.id===t.id?'active':''}" data-pfv53-theme="${t.id}" ${unlocked?'':'disabled'} style="--tc:${t.color}"><i></i><b>${t.name}</b><span>${unlocked?t.sub:`Reach ${rank?.name||'this rank'} to unlock`}</span><em>${active.id===t.id?'ACTIVE':unlocked?'SELECT':'LOCKED'}</em></button>`}).join('')}</div><div class="pfv53-theme-note">Highest unlocked style: <b>${PF_ARENA_RANKS[Math.min(best,PF_ARENA_RANKS.length-1)]?.name||'Bronze'}</b> · visual only, no combat bonus.</div>`;host.querySelectorAll('[data-pfv53-theme]:not(:disabled)').forEach(b=>b.onclick=()=>{state.settings.pfTheme=b.dataset.pfv53Theme;pfv53ApplyTheme();save(true);pfv53RenderThemes()})}

  const pfv53MountExtraBase=pfV34MountExtraHub;
