  /* Bosses have personalities rather than only a larger skill number. */
  const pfv56AIBase=aiChoose;
  aiChoose=function(offers,phase){
    let pick=pfv56AIBase(offers,phase),boss=pfArenaFight?.boss;if(!boss||!offers?.length)return pick;
    const r=Math.random();if(r>.42)return pick;
    if(phase==='attack'&&['aggressive','gambler','precision'].includes(boss.style)){
      const pool=offers.slice().sort((a,b)=>((b.damage||0)*(b.chance||1))-((a.damage||0)*(a.chance||1)));
      if(boss.style==='gambler'){const risk=offers.filter(x=>pfv56HasChance(x)).sort((a,b)=>(a.chance||1)-(b.chance||1));if(risk.length)return risk[0]}
      return pool[0]||pick
    }
    if(phase==='closing'&&boss.style==='wall'){const pool=offers.filter(x=>['heal','guard'].includes(x.role));if(pool.length)return pool[Math.floor(Math.random()*pool.length)]}
    if(phase==='setup'&&boss.style==='speed'){const pool=offers.filter(x=>/initiative|speed/i.test(x.desc||'')||x.id==='adrenaline'||x.id==='ambush_step');if(pool.length)return pool[Math.floor(Math.random()*pool.length)]}
    return pick
  };

  const pfv56FinishBase=pfArenaFinish;
