  /* Round-rule strip and boss status are visual only; no particles/loops, Chromebook friendly. */
  try{if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.unshift({version:PFV56,title:'Promotion Bosses + Dynamic Clashes',items:['Arena cooldowns were removed; move rotation now comes entirely from the three-offer shuffle.','Only high-payoff moves show a chance badge, written as “XX% OF WORKING”; ordinary moves always work.','Promotion games at the top of Division 3 become named boss battles with distinct AI tendencies and a short boss intro.','Later rounds can roll a lightweight clash rule such as Overdrive, Second Wind, Sharp Read, or Wild Card to keep fights from repeating the same rhythm.']})}}catch(e){}
  window.__pfArenaV356={version:PFV56,boss:()=>pfv56BossForMatch(),rules:PFV56_RULES,battle:()=>pfArenaFight,pools:()=>({phase1:SETUP.map(x=>({id:x.id,chance:pfv56HasChance(x)?pfv56ChancePct(x):null})),phase2:ATTACK.map(x=>({id:x.id,chance:pfv56HasChance(x)?pfv56ChancePct(x):null})),phase3:CLOSING.map(x=>({id:x.id,chance:pfv56HasChance(x)?pfv56ChancePct(x):null}))})};


  window.__pfArenaV355={version:PFV55,chance:o=>pfv55ChanceLabel(o),battle:()=>pfArenaFight,pools:()=>({phase1:SETUP.map(x=>({id:x.id,chance:pfv55ChanceLabel(x)})),phase2:ATTACK.map(x=>({id:x.id,chance:pfv55ChanceLabel(x)})),phase3:CLOSING.map(x=>({id:x.id,chance:pfv55ChanceLabel(x)}))})};
  try{if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.unshift({version:PFV55,title:'Chance Layer + Battle Transitions',items:['Every Arena move now exposes a success percentage directly on its choice card.','Low-odds moves such as Meteor Crash trade reliability for much larger effects; the rival can roll and choose the same chance moves.','Correct phase predictions now trigger a dedicated READ RIGHT +25% card burst.','Manual swaps, rival swaps, knockouts, and automatic replacements have dedicated transition animations.']})}}catch(e){}


  window.__pfArenaV354={version:PFV54,division:()=>pfv54Division(),divisions:PFV54_DIVISIONS,rewards:()=>pfv54Rewards(),rivals:PFV54_RIVAL,battle:()=>pfArenaFight};
  try{if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.unshift({version:PFV54,title:'Arena Divisions + Rewards',items:['Themes were removed; rank no longer recolors the main PackForge top ribbon.','Every rank now has divisions 1, 2 and 3 while preserving 100 RP Bronze/Silver/Gold and 250 RP Platinum+ major tiers.','Rarity growth is roughly 1.15× per step, with deterministic 1.12×–1.18× card personality and compressed battle damage.','Shield storage is capped at 6% max Health and all new shield gains are cut in half again.','Gold rival decks now almost always contain Legendary/Mythic cards; AI and swapping scale upward through the 21 divisions.','Completed matches award cash and normal packs; wins also roll rising Special/Graded/High-Roller/Secret Hunt chances.','First-time division promotions grant 1–15 Special Packs plus higher-tier premium bonuses.']})}}catch(e){}

  window.__pfArenaV353={version:PFV53,stats:(card,copy={},level=1)=>pfCardCombatStats(card,copy,level),themes:PFV53_THEMES,pools:()=>({phase1:SETUP.map(x=>x.id),phase2:ATTACK.map(x=>x.id),phase3:CLOSING.map(x=>x.id)}),battle:()=>pfArenaFight};
  try{if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.unshift({version:PFV53,title:'Tactical Mix + Rank Themes',items:['Phase 1 now rotates tactical tradeoffs, tempo tools, risk/reward plays and a rare Golden Contract that can add 20% match cash without helping combat.','Phase 3 is dedicated to healing, shielding and sustain choices with much smaller shield values and a 14%-of-max shield cap.','Rarity scaling is rebuilt around roughly 20–25% Health growth per normal rarity step, gentler Attack growth and small Speed growth; battle damage converts Attack softly to prevent one-shot chains.','Extra now includes Themes. Rank themes unlock as you climb and style the whole game with CSS-only effects that disable under performance/reduced-motion modes.','No new remote assets, fetches, timers or particle loops were added.']})}}catch(e){}

  window.__pfArenaV352={version:PFV52,ranges:PFV52_RANGES,battle:()=>pfArenaFight,rank:()=>pfArenaRank(),forcedRival:()=>state.arena?.adminRivalRank||null};
  try{if(Array.isArray(PF320_PLAYER_LOG)){PF320_PLAYER_LOG.unshift({version:PFV52,title:'Arena Balance + Admin Lab',items:['Secret+ cards keep their large Health advantage, but Attack now uses stronger diminishing returns and normal hits cannot erase a full-health card in one shot.','All shield gains are reduced by 50%.','Bronze, Silver and Gold remain 100-RP ranks; Platinum, Diamond and Master now each take 250 RP to clear.','The Arena admin tab now includes exact RP controls, forced rival-rank testing, live battle tools, a 5-card test deck generator, placement controls and reset tools.']})}}catch(e){}
