    let healMult=effectMult*(s.v59HealAmp||1)*sustainDown;if((a.heal||a.healLow)&&s.v59HealAmp)s.v59HealAmp=1;if(a.heal){const n=pfHeal(f,f.maxHp*a.heal*healMult);if(n)pfv59CardFx(who,'pfv47-healhop',`+${n} HP`,'shield')}
    if(a.healLow){const pct=f.hp/f.maxHp<.4?a.healLow:a.healHigh,n=pfHeal(f,f.maxHp*pct*healMult);if(n)pfv59CardFx(who,'pfv47-healhop',`+${n} HP`,'shield')}
