  pfv60Patch('quick_cut',{damage:18,speed:10,speedBuff:2,copy:'18 damage. Gain +2 Speed next turn.'});
  pfv60Patch('heavy_slam',{damage:32,sunder:.20,speed:1,copy:'32 damage. Rival shield gain is 20% weaker next turn.'});
  pfv60Patch('shield_breaker',{damage:22,pierce:.88,shieldStrip:.35,speed:5,copy:'22 damage. Break 35% of their current shield.'});
  pfv60Patch('drain_fang',{damage:20,leech:.32,speed:5,copy:'20 damage. Heal 32% of Health damage dealt.'});
  pfv60Patch('twin_strike',{damage:13,hits:2,speed:7,copy:'Two separate 13-damage hits.'});
  pfv60Patch('execution',{damage:18,execute:24,speed:4,copy:'18 damage. +24 if rival is below 35% Health.'});
  pfv60Patch('revenge',{damage:18,lowSelfBonus:18,speed:5,copy:'18 damage. +18 while you are below 35% Health.'});
  pfv60Patch('counterpunch',{damage:16,counterBonus:18,speed:6,copy:'16 damage. +18 if the rival also attacks.'});
  pfv60Patch('sunder',{damage:16,sunder:.28,speed:6,copy:'16 damage. Their next shield gain is 28% weaker.'});
  pfv60Patch('haymaker',{damage:44,chance:.54,speed:0,copy:'44 damage if it lands.'});
  pfv60Patch('meteor_crash',{damage:58,chance:.28,speed:-4,copy:'58 damage if it lands. Huge gamble.'});

  pfv60Patch('patch_up',{heal:.085,cleanseSustain:true,speed:6,copy:'Heal 8.5%. Clear one sustain penalty.'});
  pfv60Patch('second_wind',{healLow:.18,healHigh:.05,speed:5,copy:'Heal 18% when low, otherwise 5%.'});
  pfv60Patch('regrowth',{heal:.04,regen:.025,regenTurns:2,speed:5,copy:'Heal 4% now, then 2.5% for 2 turns.'});
  pfv60Patch('battle_mend',{heal:.05,damage:9,speed:5,copy:'Heal 5% and deal 9 damage.'});
  pfv60Patch('shield_recycle',{shieldToHeal:1.0,speed:8,copy:'Consume your shield and turn it into equal healing.'});
  pfv60Patch('adrenaline',{heal:.04,speedBuff:4,speed:8,copy:'Heal 4%. Gain +4 Speed next turn.'});
  pfv60Patch('miracle_recovery',{heal:.20,chance:.36,speed:3,copy:'Heal 20% of max Health if it works.'});

  pfv60Patch('brace',{shield:.014,speed:9,copy:'Gain a small shield. Fast and reliable.'});
  pfv60Patch('iron_wall',{shield:.012,guard:.10,speed:4,copy:'Small shield. Next hit deals 10% less.'});
  pfv60Patch('mirror_guard',{shield:.012,reflect:.18,speed:6,copy:'Small shield. Reflect 18% of the next HP hit.'});
  pfv60Patch('emergency_wall',{shieldLow:.028,shieldHigh:.008,speed:7,copy:'Better shield while below 40% Health.'});
  pfv60Patch('barrier_pulse',{shield:.010,healAmp:.20,speed:7,copy:'Small shield. Your next heal is 20% stronger.'});
  pfv60Patch('parry',{parry:1,chance:.48,speed:10,copy:'48% of working. If it works, block the next attack.'});
  pfv60Patch('aegis',{shield:.030,chance:.42,speed:2,copy:'42% of working. Gain a stronger shield.'});

  pfv60Patch('feint',{nextDamage:.20,speedBuff:2,speed:11,copy:'Next damaging move is 20% stronger. +2 Speed.'});
  pfv60Patch('focus',{focus:.14,speed:12,copy:'Your next risky move gets +14% chance to work.'});
  pfv60Patch('smoke_step',{dodge:.32,speed:12,copy:'32% chance to evade the next damaging move.'});
  pfv60Patch('echo_step',{echo:.32,speed:10,copy:'Your next attack repeats at 32% power.'});
