    const pSide=pfSide('player'),eSide=pfSide('enemy'),pSpeed=(pAction.speed||0)+(pfActive('player')?.speedStat||100)/50+(pSide.v59Speed||0),eSpeed=(eAction.speed||0)+(pfActive('enemy')?.speedStat||100)/50+(eSide.v59Speed||0);pSide.v59Speed=0;eSide.v59Speed=0;
