    const pSide=pfSide('player'),eSide=pfSide('enemy');pSide.v59Speed=0;eSide.v59Speed=0;
    if(F.boss?.name==='Midas'&&F.turnNo%3===0){const heads=((F.seed+F.turnNo*811)>>>0)%2===0;eSide.v59NextEffect=(eSide.v59NextEffect||1)*(heads?1.25:.75);floatFx('enemy',heads?'GILDED +25%':'GILDED -25%',heads?'shield':'damage')}
